// 41f8f0/41f610 execute; DLL rand,sector,blast,spark are recorded leaf inputs.
import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZV41BuildingFragmentCallersOracle2 extends GhidraScript{
 static final long S=0x7fff0000L,RET=0x12345000L,RAND=RET+0x1000,B=0x1800000L,P=B+0x1000,CP=B+0x2000,Q=B+0x3000;
 long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}void set(byte[]b,int a,int n,long v){for(int i=0;i<n;i++)b[a+i]=(byte)(v>>(i*8));}int hash(byte[]b){int h=0x811c9dc5;for(byte v:b)h=(h^(v&255))*16777619;return h;}String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format("%02x",v&255));return s.toString();}
 void resume(EmulatorHelper e)throws Exception{long sp=e.readRegister("ESP").longValue(),ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int mode=0;mode<2;mode++)for(int variant=0;variant<(mode==0?4:3);variant++)for(int s=0;s<16;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{int kind=mode==0?new int[]{0,1,4,8}[variant]:new int[]{4,1,8}[variant];long entry=mode==0?new long[]{0x40cd20,0x40b4e0,0x40bac0,0x40c820}[variant]:new long[]{0x40b6b0,0x40c490,0x40cb20}[variant];long table=mode==0?new long[]{0x478420,0x4782a0,0x4785b8,0x478798}[variant]:0;byte[]old=new byte[900];for(int i=0;i<50;i++){for(int j=0;j<18;j++)old[i*18+j]=(byte)(s*19+i*13+j*7);set(old,i*18,2,i<new int[]{0,25,49,50}[s%4]?100+i:-1);}if(mode==1){for(int i=0;i<50;i++)set(old,i*18,2,-1);set(old,0,2,100);set(old,2,2,200);set(old,8,2,1782);set(old,10,2,new int[]{0,10,-2,-10}[s%4]);old[12]=0;old[13]=4;old[14]=(byte)(s/4%4);old[15]=1;old[16]=2;}e.writeMemory(toAddr(P),old);e.writeMemory(toAddr(B),new byte[88]);put(e,B,2,mode==0?400:3000);put(e,B+2,2,mode==0?500:3000);put(e,B+4,1,kind);put(e,B+6,1,0xe0);put(e,B+0x18,4,P);put(e,B+0x20,4,CP);put(e,B+0x1c,2,new int[]{0,1,100,32767}[s/4%4]);put(e,B+0x1e,2,mode==0?100:new int[]{0,1,80,32767}[s/4%4]);put(e,CP+8,1,4);put(e,0x622dc2,1,0);put(e,0x622dc4,1,s&1);put(e,0x4d02db,1,0);put(e,0x622cb8,4,0);put(e,0x498c24,2,800);put(e,0x498c20,2,600);put(e,0x62b3a4,4,Q);put(e,0x4a6e72,1,13);put(e,0x4740ac,4,RAND);for(int i=0;i<5;i++)put(e,0x622cdc+4*i,4,s*(i+1)+i+1);for(long a:new long[]{RET,RAND,0x417400,0x420200,0x41dbf0,0x41f610})e.setBreakpoint(toAddr(a));put(e,S,4,RET);put(e,S+4,4,B);put(e,S+8,4,0x498c78+kind*76);e.writeRegister("ESP",S);if(!e.run(toAddr(entry),null,monitor))throw new Exception(e.getLastError());int crt=0,blast=0,spark=0,leaf=0,damage=0;long pointer=0;while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue();if(pc==0x41f610){leaf++;damage=(short)e.readRegister("EDX").intValue();pointer=e.readRegister("ECX").longValue();if(!e.step(monitor)||!e.run(monitor))throw new Exception(e.getLastError());continue;}if(pc==RAND)e.writeRegister("EAX",(s*3571+crt++*131+0x1743)&32767);else if(pc==0x417400)e.writeRegister("EAX",CP);else if(pc==0x420200)blast++;else if(pc==0x41dbf0)spark++;else throw new Exception("unexpected"+Long.toHexString(pc));resume(e);}int draws=(int)((read(e,0x62b3a4,4)-Q)/8);StringBuilder rows=new StringBuilder("[");if(mode==0){for(int i=0;i<50;i++){int x=(short)read(e,table+i*12,2);if(x==-1)break;if(i>0)rows.append(',');rows.append('[');for(int j=0;j<6;j++){if(j>0)rows.append(',');rows.append((short)read(e,table+i*12+j*2,2));}rows.append(']');}}rows.append(']');out.print("{\"mode\":"+mode+",\"variant\":"+variant+",\"scenario\":"+s+",\"kind\":"+kind+",\"entry\":"+entry+",\"table\":"+table+",\"before\":"+(hash(old)&0xffffffffL)+",\"pool\":"+(hash(e.readMemory(toAddr(P),900))&0xffffffffL)+",\"bytes\":\""+hex(e.readMemory(toAddr(P),900))+"\",\"draws\":"+draws+",\"queue\":\""+hex(draws==0?new byte[0]:e.readMemory(toAddr(Q),draws*8))+"\",\"crt\":"+crt+",\"blast\":"+blast+",\"spark\":"+spark+",\"calls\":"+leaf+",\"damage\":"+damage+",\"pointer\":"+pointer+",\"flag\":"+read(e,0x4a6e72,1)+",\"templates\":"+rows);for(int i=0;i<5;i++)out.print(",\"r"+i+"\":"+read(e,0x622cdc+i*4,4));out.println("}");}finally{e.dispose();}}}}
}
